-- Roles (not generated by Prisma migrate diff — applied before schema)
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'org_rw') THEN
    CREATE ROLE org_rw NOLOGIN NOINHERIT;
  END IF;
END $$;

DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_runtime') THEN
    EXECUTE 'GRANT org_rw TO app_runtime';
  END IF;
END $$;

-- CreateSchema
CREATE SCHEMA IF NOT EXISTS "organizations";

GRANT USAGE ON SCHEMA "organizations" TO org_rw;

DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'founder_runtime') THEN
    EXECUTE 'GRANT USAGE ON SCHEMA organizations TO founder_runtime';
  END IF;
END $$;

